from __future__ import annotations

from jinja2 import Environment

_env = Environment(autoescape=False)

_LAYOUT = """To: {{ recipient }}

{{ body }}

\u2014 Sent with NotifyHub"""


def render_message(recipient: str, body: str) -> str:
    """Render an outbound notification message for ``recipient`` from ``body``."""
    # First, render the sender-supplied body as a Jinja2 template so that
    # placeholders like {{ recipient }} get filled in.
    rendered_body = _env.from_string(body).render(recipient=recipient)
    # Then frame the rendered body in the fixed notification layout.
    return _env.from_string(_LAYOUT).render(recipient=recipient, body=rendered_body)
